-- Magnific (Freepik) — Генерація зображень
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'magnific.com' OR LOWER(`name`) = LOWER('Magnific (Freepik)'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Magnific (Freepik)', NULL, 'https://www.magnific.com', NULL, NULL, 'Креативна AI-платформа, на яку перейменовано Freepik: генерація зображень, відео, музики й 3D, AI-апскейлер і бібліотека з 250+ млн стокових матеріалів.', 'The creative AI platform Freepik has been renamed to: image, video, music and 3D generation, an AI upscaler and a library of 250M+ stock assets.', 'Magnific — так тепер називається Freepik, одна з найбільших платформ стокової графіки, що перетворилася на універсальну креативну AI-студію. В одному місці доступні генерація зображень і відео на провідних моделях, створення музики й голосу, 3D-моделі, AI-апскейлер для покращення деталізації та стокова бібліотека з понад 250 млн матеріалів. Платформою користуються понад мільйон передплатників; усі тарифи включають комерційну ліцензію на AI-контент і доступ до API. Ціни в євро при річній оплаті: Premium — €10,50 на місяць, Premium+ — €25,50, Pro Starter — €62,25; помісячна оплата на 25% дорожча.', 'Magnific is the new name of Freepik, one of the largest stock graphics platforms, now an all-in-one creative AI studio. In one place you get image and video generation on leading models, music and voice creation, 3D models, an AI upscaler for sharper detail and a stock library of more than 250 million assets. More than a million subscribers use it; all plans include a commercial licence for AI content and API access. Prices in euros billed annually: Premium — €10.50 a month, Premium+ — €25.50, Pro Starter — €62.25; monthly billing costs 25% more.', 'Генерація зображень і відео на провідних моделях
Музика, голос і 3D
AI-апскейлер
250+ млн стокових матеріалів
Комерційна ліцензія на всіх тарифах', 'Image and video generation on leading models
Music, voice and 3D
AI upscaler
250M+ stock assets
Commercial licence on all plans', 'Дизайнери, маркетологи й контент-мейкери.', 'Designers, marketers and content creators.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
