SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'upscayl.org' OR LOWER(`name`) = LOWER('Upscayl'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Upscayl', NULL, 'https://upscayl.org', NULL, NULL, 'Безкоштовний відкритий AI-апскейлер: збільшує роздільність розмитих і маленьких фото до 16 разів на Windows, macOS і Linux; є хмарна версія.', 'A free, open-source AI upscaler: it enlarges blurry and small photos up to 16× on Windows, macOS and Linux; a cloud version is also available.', 'Upscayl покращує й збільшує зображення за допомогою AI — до 16 разів від початкової роздільності, зберігаючи кольори. Настільна програма для Windows, macOS і Linux — безкоштовна й з відкритим кодом: її завантажують один раз і користуються без обмежень. Є кілька моделей під різні типи зображень, пакетна обробка й налаштування. Нещодавно запущено хмарну версію з необмеженим сховищем, пакетною обробкою та AI-покращенням облич (умови — на сторінці тарифів).', 'Upscayl enhances and enlarges images with AI — up to 16× the original resolution while preserving colour. The desktop app for Windows, macOS and Linux is free and open source: download it once and use it without limits. It offers several models for different image types, batch processing and customisation. A cloud version has recently launched with unlimited storage, batch processing and AI face enhancement (terms are on the pricing page).', 'Збільшення до 16×
Кілька моделей під різні зображення
Пакетна обробка
Безкоштовно й з відкритим кодом', 'Up to 16× upscaling
Several models for different images
Batch processing
Free and open source', 'Фотографи, дизайнери й усі, кому треба покращити старі чи маленькі фото.', 'Photographers, designers and anyone who needs to improve old or small photos.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
