-- Higgsfield — Генерація відео
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'higgsfield.ai' OR LOWER(`name`) = LOWER('Higgsfield'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Higgsfield', NULL, 'https://higgsfield.ai', NULL, NULL, 'AI-студія відео й зображень: генерує ролики, анімації та рекламу на провідних моделях з керуванням кінематографічними рухами камери.', 'An AI video and image studio: it generates clips, animations and ads on leading models with cinematic camera-movement controls.', 'Higgsfield — платформа для генерації AI-відео, анімацій і реклами. В одному інтерфейсі доступні провідні моделі генерації зображень і відео, ефекти та кінематографічні рухи камери, які складно отримати звичайним текстовим запитом. Є API та інтеграції з AI-асистентами. Тарифи для окремих користувачів і бізнесу з помісячною чи річною оплатою; поточні ціни й акції — на сторінці тарифів.', 'Higgsfield is a platform for generating AI videos, animations and ads. Leading image and video generation models, effects and cinematic camera moves that are hard to get from a plain text prompt are all available in one interface. There is an API and integrations with AI assistants. Individual and business plans are available with monthly or annual billing; current prices and promotions are on the pricing page.', 'Провідні моделі відео й зображень
