API', 'Контент-мейкери, рекламісти й SMM-фахівці.', 'Content creators, advertisers and social media managers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
